# Hypothesis: wrapping callables in a Callable[P, R]-preserving decorator leaves their
# assignability unchanged: return covariance and parameter contravariance still hold,
# and positional-only protocol compatibility is unaffected.
from typing import Callable, ParamSpec, Protocol, TypeVar, reveal_type, assert_type

P = ParamSpec('P')
R = TypeVar('R')


def keep_sig(fn: Callable[P, R]) -> Callable[P, R]:
    def inner(*args: P.args, **kwargs: P.kwargs) -> R:
        return fn(*args, **kwargs)

    return inner


class PosOnly(Protocol):
    def __call__(self, b: int, a: int, /) -> None: ...


class Standard(Protocol):
    def __call__(self, a: int, b: int) -> None: ...


@keep_sig
def to_int_from_float(x: float) -> int:
    return int(x)


@keep_sig
def add_one(x: int) -> int:
    return x + 1


@keep_sig
def std_impl(a: int, b: int) -> None:
    pass


@keep_sig
def pos_impl(b: int, a: int, /) -> None:
    pass


def use_int_to_float(f: Callable[[int], float]) -> float:
    return f(3)


f1: Callable[[int], float] = to_int_from_float  # OK
f2: Callable[[int], int] = to_int_from_float  # OK
f3: Callable[[float], float] = add_one  # expect-error
reveal_type(to_int_from_float)
assert_type(use_int_to_float(to_int_from_float), float)
assert use_int_to_float(to_int_from_float) == 3
assert f1(3) == 3 and f2(3) == 3
pos_p: PosOnly = std_impl  # OK
std_p: Standard = pos_impl  # expect-error
pos_p(2, 1)
std_p(1, 2)
assert add_one(4) == 5
